#!/usr/bin/env bash
# instalar-motor.sh — installs the engine (instance server + built page) on a small server.
# GENERATED by `node tools/build-deploy.mjs` from deploy/instalar-motor.plantilla.sh. Do not edit the
# generated file: edit the template and regenerate. Everything it needs travels inside this one file.
#
# Targets: Ubuntu 24.04 or Debian 12, x86_64 or arm64, run as root.
#   sudo bash instalar-motor.sh                        HTTP by IP (tests): http://<ip>/
#   sudo bash instalar-motor.sh --dominio motor.ejemplo.com   automatic HTTPS (DNS must point here)
#   Other options: --memoria 75%   (systemd MemoryMax for the instance, default 75% of RAM)
#                  --sin-cortafuegos  (do not touch ufw)
#                  --sin-habitantes   (no AI inhabitants: stops and disables numinia-habitantes if it was there)
#                  --auto-actualizar  (timer: installs every new release of GitHub by itself, sha256 checked; actualizar.sh)
#                  --sin-auto-actualizar · --sin-dominio (back to HTTP by IP)
#                  --construir todos|nadie  (who may place and move things in the world; default todos, until roles: H3)
#                  --clave-ia  (asks, without showing it, the Claude key for the AI inhabitants' brain; checks it with
#                              Anthropic and keeps it in /opt/numinia-engine/cerebro.env) · --modelo-ia ID · --quitar-clave-ia
#   Options are saved in /opt/numinia-engine/instalacion.env: a later run without them keeps them (the updater relies on it).
#   bash instalar-motor.sh --solo-extraer DIR   unpack app/ and www/ into DIR, install nothing (no root)
#   bash instalar-motor.sh --version            print what is inside
#   sudo bash instalar-motor.sh --desinstalar   stop and remove the engine's services, its Caddy (masked: 80/443 free)
#                                               and /opt/numinia-engine; KEEPS the world (/var/lib/numinia-motor);
#                                               never touches ssh or ufw. Then the fleet's bootstrap can take the machine.
#
# What it does: official Node LTS (sha256 checked) in /opt/numinia-engine/node, system user
# `numinia`, systemd service `numinia-motor` (127.0.0.1:8790, LimitNOFILE, MemoryMax, hardening),
# Caddy serving the page and passing /ws to the instance, ufw allowing ssh/80/443.
# The world is ONE folder, /var/lib/numinia-motor (MOTOR_MUNDO): datos/, aventura/ (its own adventure: a copy of the
# example the first time), entorno/, sesiones/ — the same layout as a container's /mundo.
# The world as a zip: https://<domain>/mundo downloads it and uploads one, with the administration code that this
# script makes once in /opt/numinia-engine/admin.env (sudo cat it; it is never printed).
# P4: a second service `numinia-habitantes` (own system user, localhost only, no route in Caddy) runs the AI
# inhabitants of the adventure (escalón 0: a script, no language model, no provider key). Off switch:
# `systemctl stop numinia-habitantes` and the world goes on without them.
set -euo pipefail

BUILD="__BUILD__"
NODE_VERSION="__NODE_VERSION__"
NODE_SHA256_X64="__NODE_SHA256_X64__"
NODE_SHA256_ARM64="__NODE_SHA256_ARM64__"
PREFIX=/opt/numinia-engine
SERVICE=numinia-motor
USER_NAME=numinia
PORT=8790
HAB_SERVICE=numinia-habitantes
HAB_USER=numinia-hab
ACT_SERVICE=numinia-actualizar
STATE=/var/lib/numinia-motor   # the world folder (C2): what --desinstalar keeps

say() { printf '\033[1m[motor]\033[0m %s\n' "$*"; }
die() { printf '\033[31m[motor] ERROR:\033[0m %s\n' "$*" >&2; exit 1; }

extract_payload() { # $1 = destination directory
  mkdir -p "$1"
  awk 'found { print } /^__CARGA_DEBAJO__$/ { found = 1 }' "$0" | base64 -d | tar -xz -C "$1"
}

DOMAIN=""; MEMORY="75%"; FIREWALL=1; ONLY_EXTRACT=""; HABITANTES=1; AUTO=0; CONSTRUIR=todos; CLAVE_IA=""; MODELO_IA=""; DESINSTALAR=0
DADO=" " # the options given on this run; the rest come from instalacion.env when there is one
while [ $# -gt 0 ]; do
  case "$1" in
    --dominio) DOMAIN=${2:?falta el dominio, p. ej. --dominio motor.ejemplo.com}; DADO+="DOMAIN "; shift 2 ;;
    --sin-dominio) DOMAIN=""; DADO+="DOMAIN "; shift ;;
    --memoria) MEMORY=${2:?falta el valor, p. ej. --memoria 1G o --memoria 75%}; DADO+="MEMORY "; shift 2 ;;
    --sin-cortafuegos) FIREWALL=0; DADO+="FIREWALL "; shift ;;
    --sin-habitantes) HABITANTES=0; DADO+="HABITANTES "; shift ;;
    --auto-actualizar) AUTO=1; DADO+="AUTO "; shift ;;
    --sin-auto-actualizar) AUTO=0; DADO+="AUTO "; shift ;;
    --construir) CONSTRUIR=${2:?falta todos o nadie}; DADO+="CONSTRUIR "; shift 2 ;;
    --clave-ia) CLAVE_IA=pedir; shift ;;
    --quitar-clave-ia) CLAVE_IA=quitar; shift ;;
    --modelo-ia) MODELO_IA=${2:?falta el modelo, p. ej. --modelo-ia claude-sonnet-5}; shift 2 ;;
    --solo-extraer) ONLY_EXTRACT=${2:?falta la carpeta destino}; shift 2 ;;
    --desinstalar) DESINSTALAR=1; shift ;;
    --version) echo "numinia-engine $BUILD · Node $NODE_VERSION"; exit 0 ;;
    -h|--help) sed -n '2,33p' "$0"; exit 0 ;;
    *) die "opción desconocida '$1'. Usa --help para ver las opciones." ;;
  esac
done

if [ -n "$ONLY_EXTRACT" ]; then
  extract_payload "$ONLY_EXTRACT"
  say "extraído en $ONLY_EXTRACT (app/ = servidor, www/ = página). Nada instalado."
  exit 0
fi

# ---------- --desinstalar: the machine goes back to having no engine; the world stays ----------
if [ "$DESINSTALAR" = 1 ]; then
  [ "$(id -u)" -eq 0 ] || die "hay que ejecutarlo como root: sudo bash $0 --desinstalar"
  command -v systemctl > /dev/null || die "no hay systemd; no hay nada que desinstalar"
  say "desinstalo el motor de esta máquina (el mundo se queda en $STATE)"
  for u in "$ACT_SERVICE.timer" "$ACT_SERVICE.service" "$HAB_SERVICE.service" "$SERVICE.service"; do
    systemctl disable --now "$u" > /dev/null 2>&1 || true
    rm -f "/etc/systemd/system/$u"
  done
  systemctl daemon-reload
  systemctl reset-failed > /dev/null 2>&1 || true
  if [ -n "$(systemctl list-unit-files caddy.service --no-legend 2> /dev/null)" ]; then
    # 80 and 443 free for the fleet's Caddy (in Docker); masked so neither a reboot nor an apt upgrade starts it again
    # (instalar-motor.sh unmasks it if the engine is installed here again)
    systemctl disable --now caddy > /dev/null 2>&1 || true
    systemctl mask caddy > /dev/null 2>&1 || true
    say "Caddy del sistema parado, desactivado y enmascarado: los puertos 80 y 443 quedan libres"
  fi
  # the program and its keys (secret, administration code, agents' secret, the Claude key): the fleet makes its own
  rm -rf "$PREFIX"
  say "quitados: $SERVICE, $HAB_SERVICE, $ACT_SERVICE y $PREFIX (el programa y sus claves)"
  if [ -d "$STATE" ]; then say "el mundo sigue en $STATE ($(ls "$STATE" 2> /dev/null | tr '\n' ' ')): no lo he tocado"; else say "no había mundo en $STATE"; fi
  say "no he tocado ssh ni el cortafuegos (ufw). La máquina puede entrar ya en la flota (la línea de alta de la sala de Mundos)."
  exit 0
fi

# ---------- checks ----------
[ "$(id -u)" -eq 0 ] || die "hay que ejecutarlo como root: sudo bash $0"
case "$DOMAIN" in ""|*[!A-Za-z0-9.-]*) [ -z "$DOMAIN" ] || die "el dominio '$DOMAIN' no vale (solo letras, números, puntos y guiones)" ;; esac
case "$MEMORY" in *[!0-9KMGT%]*|"") die "--memoria '$MEMORY' no vale (p. ej. 1G o 75%)" ;; esac
case "$CONSTRUIR" in todos|nadie) ;; *) die "--construir '$CONSTRUIR' no vale: todos o nadie" ;; esac
case "$MODELO_IA" in ""|claude-[a-z0-9.-]*) ;; *) die "--modelo-ia '$MODELO_IA' no parece un modelo de Claude (claude-…)" ;; esac
if [ "$CLAVE_IA" = pedir ] && [ ! -r /dev/tty ]; then die "--clave-ia pregunta la clave en la terminal: ejecútalo en una terminal, no en segundo plano"; fi
# the options of the last install, for what this run did not say (the updater runs the new installer with no options)
if [ -f "$PREFIX/instalacion.env" ]; then
  while IFS='=' read -r k v; do
    case "$k" in DOMAIN|MEMORY|FIREWALL|HABITANTES|AUTO|CONSTRUIR) ;; *) continue ;; esac
    case "$DADO" in *" $k "*) continue ;; esac
    case "$k:$v" in DOMAIN:|DOMAIN:[A-Za-z0-9]*[A-Za-z0-9]|MEMORY:[0-9]*|FIREWALL:[01]|HABITANTES:[01]|AUTO:[01]|CONSTRUIR:todos|CONSTRUIR:nadie) printf -v "$k" '%s' "$v" ;; esac
  done < "$PREFIX/instalacion.env"
  say "opciones guardadas de la instalación anterior: dominio ${DOMAIN:-ninguno} · memoria $MEMORY · cortafuegos $FIREWALL · habitantes $HABITANTES · auto-actualizar $AUTO · construir $CONSTRUIR"
fi
. /etc/os-release
case "${ID:-}-${VERSION_ID:-}" in
  ubuntu-24.04|debian-12) say "sistema $PRETTY_NAME" ;;
  *) say "AVISO: probado para Ubuntu 24.04 y Debian 12; este es ${PRETTY_NAME:-desconocido}. Sigo." ;;
esac
command -v systemctl > /dev/null || die "no hay systemd; este instalador lo necesita"
case "$(uname -m)" in
  x86_64) ARCH=x64; NODE_SHA=$NODE_SHA256_X64 ;;
  aarch64) ARCH=arm64; NODE_SHA=$NODE_SHA256_ARM64 ;;
  *) die "arquitectura $(uname -m) no soportada (solo x86_64 y aarch64)" ;;
esac

# ---------- system packages ----------
say "paquetes del sistema (curl, xz, caddy, ufw)"
export DEBIAN_FRONTEND=noninteractive
apt-get update -q
apt-get install -y -q ca-certificates curl xz-utils caddy ufw > /dev/null

# ---------- Node LTS, checked against the sha256 pinned at build time ----------
mkdir -p "$PREFIX"
if [ "$("$PREFIX/node/bin/node" --version 2> /dev/null || true)" != "v$NODE_VERSION" ]; then
  say "Node $NODE_VERSION ($ARCH)"
  tmp=$(mktemp -d)
  tarball="node-v$NODE_VERSION-linux-$ARCH.tar.xz"
  curl -fsSL --retry 3 -o "$tmp/$tarball" "https://nodejs.org/dist/v$NODE_VERSION/$tarball"
  echo "$NODE_SHA  $tmp/$tarball" | sha256sum -c --quiet - || die "la suma sha256 de Node no coincide: descarga corrupta o manipulada"
  rm -rf "$PREFIX/node.new"; mkdir -p "$PREFIX/node.new"
  tar -xJf "$tmp/$tarball" -C "$PREFIX/node.new" --strip-components=1
  rm -rf "$PREFIX/node"; mv "$PREFIX/node.new" "$PREFIX/node"; rm -rf "$tmp"
else
  say "Node $NODE_VERSION ya estaba"
fi

# ---------- system user ----------
id "$USER_NAME" > /dev/null 2>&1 || useradd --system --home-dir "$PREFIX" --no-create-home --shell /usr/sbin/nologin "$USER_NAME"

# ---------- the engine itself (server sources + built page) ----------
say "motor $BUILD"
rm -rf "$PREFIX/new"; extract_payload "$PREFIX/new"
chown -R root:root "$PREFIX/new"; chmod -R a+rX "$PREFIX/new"
for d in app www; do rm -rf "$PREFIX/$d.old"; [ -d "$PREFIX/$d" ] && mv "$PREFIX/$d" "$PREFIX/$d.old"; mv "$PREFIX/new/$d" "$PREFIX/$d"; done
install -m 0755 "$PREFIX/new/actualizar.sh" "$PREFIX/actualizar.sh" # the updater (used by the timer with --auto-actualizar)
rm -rf "$PREFIX/new" "$PREFIX/app.old" "$PREFIX/www.old"
echo "$BUILD" > "$PREFIX/VERSION"

# ---------- the world folder (C2): it carries its own adventure ----------
# A world without one gets a copy of the example once; from then on it is the world's (a newer engine never swaps it).
# datos/ and sesiones/ stay where they always were; the engine reads them all from MOTOR_MUNDO.
if [ ! -d "$STATE/aventura" ]; then
  mkdir -p "$STATE"
  rm -rf "$STATE/.aventura-nueva"; cp -r "$PREFIX/app/aventuras/ejemplo" "$STATE/.aventura-nueva"
  chown -R "$USER_NAME:$USER_NAME" "$STATE/.aventura-nueva"; mv "$STATE/.aventura-nueva" "$STATE/aventura"
  say "mundo: su aventura es una copia de la de ejemplo ($STATE/aventura); desde ahora es suya"
fi

# ---------- systemd service ----------
# R1: the secret that signs the QR URLs. Made once, kept across reinstalls, readable by root only (systemd reads it).
if [ ! -f "$PREFIX/secreto.env" ]; then
  ( umask 077; echo "MOTOR_SECRET=$(head -c 24 /dev/urandom | od -An -tx1 | tr -d ' \n')" > "$PREFIX/secreto.env" )
fi
# P4: the secret that signs the AI inhabitants' tickets: apart from MOTOR_SECRET, so the inhabitants' service can make
# agent identities and never guest ones. Made once, kept across reinstalls, read by systemd (root) for both units.
if [ ! -f "$PREFIX/agentes.env" ]; then
  ( umask 077; echo "MOTOR_AGENTES_SECRET=$(head -c 24 /dev/urandom | od -An -tx1 | tr -d ' \n')" > "$PREFIX/agentes.env" )
fi
# The code that downloads and uploads the world as a zip (/mundo), until H3 brings roles. Made once, kept across
# reinstalls, readable by root only; never printed: sudo cat /opt/numinia-engine/admin.env
if [ ! -f "$PREFIX/admin.env" ]; then
  ( umask 077; echo "MOTOR_ADMIN=$(head -c 24 /dev/urandom | od -An -tx1 | tr -d ' \n')" > "$PREFIX/admin.env" )
fi
cat > "/etc/systemd/system/$SERVICE.service" << UNIT
[Unit]
Description=numinia-engine instance server ($BUILD)
After=network-online.target
Wants=network-online.target

[Service]
User=$USER_NAME
Group=$USER_NAME
WorkingDirectory=$PREFIX/app
Environment=PORT=$PORT HOST=127.0.0.1 STATS_MS=30000 NODE_ENV=production MOTOR_MUNDO=$STATE SESIONES_DIR=$STATE/sesiones DATOS_DIR=/var/lib/numinia-motor/datos ACTIVOS_DIR=/var/lib/numinia-motor/datos/activos MOTOR_CONSTRUIR=$CONSTRUIR
# C2: the whole world in one folder (datos/, aventura/, entorno/, sesiones/), the same layout as a container's /mundo
# H1: who may place, move and delete things (--construir todos|nadie; todos = people and AI inhabitants alike, until H3 roles)
# T1: how each player entered (device, browser, XR, frames), one JSONL per UTC day, 14 days, no IP
# S4: what the game features keep across restarts (datos/<feature>.json + .jsonl); back it up with the folder
# H9: what builders upload (datos/activos/<sha256>.<ext> + subidas.jsonl: who, when); the server creates it; same backup
StateDirectory=numinia-motor
EnvironmentFile=$PREFIX/secreto.env
EnvironmentFile=$PREFIX/agentes.env
EnvironmentFile=$PREFIX/admin.env
ExecStart=$PREFIX/node/bin/node packages/server/src/main.ts
Restart=always
RestartSec=2
LimitNOFILE=65536
MemoryMax=$MEMORY
TasksMax=256
NoNewPrivileges=yes
ProtectSystem=strict
ProtectHome=yes
PrivateTmp=yes
PrivateDevices=yes
ProtectKernelTunables=yes
ProtectKernelModules=yes
ProtectControlGroups=yes
RestrictAddressFamilies=AF_INET AF_INET6 AF_UNIX
LockPersonality=yes

[Install]
WantedBy=multi-user.target
UNIT
systemctl daemon-reload
systemctl enable "$SERVICE" > /dev/null 2>&1
systemctl restart "$SERVICE"

# ---------- P4: the AI inhabitants (a second service, apart from the engine's tick) ----------
if [ "$HABITANTES" = 1 ]; then
  say "habitantes IA (servicio $HAB_SERVICE: guion sin LLM, solo hablan con el motor de esta máquina)"
  id "$HAB_USER" > /dev/null 2>&1 || useradd --system --home-dir "$PREFIX" --no-create-home --shell /usr/sbin/nologin "$HAB_USER"
  # P5a: the brain's key (Claude). Asked without echo, checked with Anthropic, kept for this service only (0640
  # root:numinia-hab, read by systemd). Never printed, never in the world, never in git. Without it: the script (E0).
  if [ "$CLAVE_IA" = quitar ]; then rm -f "$PREFIX/cerebro.env"; say "clave del cerebro quitada: los habitantes contestan con su guion"; fi
  if [ "$CLAVE_IA" = pedir ]; then
    printf '  Clave de Claude (no se ve al escribir; Enter para no cambiarla): ' > /dev/tty
    IFS= read -rs CLAVE < /dev/tty; echo > /dev/tty
    if [ -n "$CLAVE" ]; then
      MODELOS=$(K="$CLAVE" "$PREFIX/node/bin/node" -e '
        fetch("https://api.anthropic.com/v1/models?limit=100", { headers: { "x-api-key": process.env.K, "anthropic-version": "2023-06-01" } })
          .then(async (r) => { if (!r.ok) { console.error("HTTP " + r.status); process.exit(2) } const d = await r.json(); console.log(d.data.map((m) => m.id).join("\n")) })
          .catch((e) => { console.error(e.message); process.exit(3) })') || die "Anthropic no acepta esa clave (o el servidor no sale a internet). No he guardado nada."
      if [ -z "$MODELO_IA" ]; then MODELO_IA=$(printf '%s\n' "$MODELOS" | grep -m1 -i sonnet || printf '%s\n' "$MODELOS" | grep -m1 -i haiku || printf '%s\n' "$MODELOS" | head -1); fi
      printf '%s\n' "$MODELOS" | grep -qx "$MODELO_IA" || die "tu cuenta no tiene el modelo $MODELO_IA. Tiene: $(printf '%s ' $MODELOS)"
      ( umask 027; printf 'CEREBRO_CLAVE=%s\nCEREBRO_MODELO=%s\nCEREBRO_DIA_MAX=300\n' "$CLAVE" "$MODELO_IA" > "$PREFIX/cerebro.env" )
      chown root:"$HAB_USER" "$PREFIX/cerebro.env"; chmod 0640 "$PREFIX/cerebro.env"
      unset CLAVE MODELOS
      say "cerebro: clave aceptada por Anthropic, modelo $MODELO_IA, tope 300 llamadas al día (en $PREFIX/cerebro.env)"
    fi
  elif [ -n "$MODELO_IA" ] && [ -f "$PREFIX/cerebro.env" ]; then
    sed -i "s/^CEREBRO_MODELO=.*/CEREBRO_MODELO=$MODELO_IA/" "$PREFIX/cerebro.env"; say "cerebro: modelo $MODELO_IA"
  fi
  # the brain talks to Anthropic only (its published inbound ranges, read 2026-10-15); without a key, localhost only
  HAB_IPS=localhost
  [ -f "$PREFIX/cerebro.env" ] && HAB_IPS="localhost 160.79.104.0/23 2607:6bc0::/48"
  cat > "/etc/systemd/system/$HAB_SERVICE.service" << UNIT
[Unit]
Description=numinia-engine AI inhabitants ($BUILD)
After=$SERVICE.service
Wants=$SERVICE.service

[Service]
User=$HAB_USER
Group=$HAB_USER
WorkingDirectory=$PREFIX/app
Environment=MOTOR_URL=ws://127.0.0.1:$PORT NODE_ENV=production STATS_MS=300000 AVENTURA_DIR=$STATE/aventura
# the inhabitants are the ones of the world's OWN adventure (the same folder the engine reads)
EnvironmentFile=$PREFIX/agentes.env
EnvironmentFile=-$PREFIX/cerebro.env
ExecStart=$PREFIX/node/bin/node packages/agent/src/main.ts
Restart=always
RestartSec=5
Nice=10
CPUQuota=50%
MemoryMax=256M
TasksMax=64
NoNewPrivileges=yes
ProtectSystem=strict
ProtectHome=yes
PrivateTmp=yes
PrivateDevices=yes
ProtectKernelTunables=yes
ProtectKernelModules=yes
ProtectControlGroups=yes
RestrictAddressFamilies=AF_INET AF_INET6
# it talks to the engine on this machine and, with a brain, to Anthropic's API; nothing else
IPAddressDeny=any
IPAddressAllow=$HAB_IPS
LockPersonality=yes

[Install]
WantedBy=multi-user.target
UNIT
  systemctl daemon-reload
  systemctl enable "$HAB_SERVICE" > /dev/null 2>&1
  systemctl restart "$HAB_SERVICE"
elif [ -f "/etc/systemd/system/$HAB_SERVICE.service" ]; then
  say "sin habitantes: paro y desactivo $HAB_SERVICE"
  systemctl disable --now "$HAB_SERVICE" > /dev/null 2>&1 || true
fi

# ---------- Caddy: page + /ws on the same origin ----------
SITE=${DOMAIN:-:80}
if [ -f /etc/caddy/Caddyfile ] && ! grep -q 'numinia-engine' /etc/caddy/Caddyfile; then
  cp /etc/caddy/Caddyfile /etc/caddy/Caddyfile.antes-del-motor
fi
cat > /etc/caddy/Caddyfile << CADDY
# numinia-engine — written by instalar-motor.sh ($BUILD)
$SITE {
	encode zstd gzip
	handle /ws {
		reverse_proxy 127.0.0.1:$PORT
	}
	# /health is public (ok + version); /metrics stays on 127.0.0.1:$PORT (ssh -L to read it from home)
	handle /health {
		reverse_proxy 127.0.0.1:$PORT
	}
	# R1: the signed URLs a QR opens (never /metrics)
	handle /e/* {
		reverse_proxy 127.0.0.1:$PORT
	}
	# H1 + H9: files of things in the world, by their sha256 — GET/HEAD for everyone, PUT (uploads) only for who may
	# build (the server checks the guest token and the caps: 12 MB per .glb, see limits.json); no size limit here
	handle /a/* {
		reverse_proxy 127.0.0.1:$PORT
	}
	# the world as a zip: the page, the download and the upload (the server asks the administration code; no size limit here)
	handle /mundo* {
		reverse_proxy 127.0.0.1:$PORT
	}
	handle {
		root * $PREFIX/www
		@hashed path /assets/*
		header @hashed Cache-Control "public, max-age=31536000, immutable"
		file_server
	}
}
CADDY
caddy validate --config /etc/caddy/Caddyfile --adapter caddyfile > /dev/null 2>&1 || die "Caddy no acepta /etc/caddy/Caddyfile (caddy validate --config /etc/caddy/Caddyfile)"
systemctl unmask caddy > /dev/null 2>&1 || true # --desinstalar masks it
systemctl enable caddy > /dev/null 2>&1
systemctl reload caddy 2> /dev/null || systemctl restart caddy

# ---------- updates from GitHub by themselves (--auto-actualizar) ----------
if [ "$AUTO" = 1 ]; then
  say "auto-actualizar: cada 10 min mira la última versión publicada en GitHub (journalctl -u $ACT_SERVICE)"
  cat > "/etc/systemd/system/$ACT_SERVICE.service" << UNIT
[Unit]
Description=numinia-engine: install the newest release from GitHub (sha256 checked)
After=network-online.target
Wants=network-online.target

[Service]
Type=oneshot
ExecStart=/usr/bin/bash $PREFIX/actualizar.sh
Nice=10
TimeoutStartSec=30min
UNIT
  cat > "/etc/systemd/system/$ACT_SERVICE.timer" << UNIT
[Unit]
Description=numinia-engine: look for a new release every 10 minutes

[Timer]
OnBootSec=5min
OnUnitActiveSec=10min
RandomizedDelaySec=60

[Install]
WantedBy=timers.target
UNIT
  systemctl daemon-reload
  systemctl enable "$ACT_SERVICE.timer" > /dev/null 2>&1
  systemctl start "$ACT_SERVICE.timer"
elif [ -f "/etc/systemd/system/$ACT_SERVICE.timer" ]; then
  say "sin auto-actualizar: paro el temporizador $ACT_SERVICE"
  systemctl disable --now "$ACT_SERVICE.timer" > /dev/null 2>&1 || true
fi

# ---------- firewall: never lock ssh out ----------
if [ "$FIREWALL" = 1 ]; then
  say "cortafuegos (ufw): ssh, 80, 443"
  ssh_ports=$(ss -ltnpH 2> /dev/null | awk '/sshd/ { n = split($4, a, ":"); print a[n] }' | sort -u)
  for p in ${ssh_ports:-22}; do ufw allow "$p/tcp" > /dev/null; done
  ufw allow 22/tcp > /dev/null
  ufw allow 80/tcp > /dev/null
  ufw allow 443/tcp > /dev/null
  ufw allow 443/udp > /dev/null
  ufw --force enable > /dev/null
fi

# ---------- check ----------
sleep 2
systemctl is-active --quiet "$SERVICE" || die "el servicio no arrancó: journalctl -u $SERVICE -n 50"
curl -fsS -o /dev/null "http://127.0.0.1/" -H "Host: ${DOMAIN:-localhost}" 2> /dev/null \
  || say "AVISO: Caddy aún no responde en el puerto 80 (con dominio, puede estar pidiendo el certificado)"
IP=$(hostname -I 2> /dev/null | awk '{ print $1 }')
if [ "$HABITANTES" = 1 ]; then
  systemctl is-active --quiet "$HAB_SERVICE" || say "AVISO: $HAB_SERVICE no arrancó (el mundo sigue sin ellos): journalctl -u $HAB_SERVICE -n 50"
fi
# what this install was, for the next run without options (and the updater), and the installer itself to go back to
( umask 077; printf 'DOMAIN=%s\nMEMORY=%s\nFIREWALL=%s\nHABITANTES=%s\nAUTO=%s\nCONSTRUIR=%s\n' "$DOMAIN" "$MEMORY" "$FIREWALL" "$HABITANTES" "$AUTO" "$CONSTRUIR" > "$PREFIX/instalacion.env" )
[ -f "$0" ] && [ "$(readlink -f "$0")" != "$PREFIX/instalador.sh" ] && install -m 0700 "$0" "$PREFIX/instalador.sh"
say "listo. Servicio $SERVICE activo, $BUILD."
if [ -n "$DOMAIN" ]; then WEB="https://$DOMAIN"; else WEB="http://${IP:-<ip-del-servidor>}"; fi
if [ -n "$DOMAIN" ]; then say "abre $WEB/"; else say "abre $WEB/  (HTTP sin cifrar: solo para pruebas)"; fi
say "el mundo en un zip (bajar y subir): $WEB/mundo · código: sudo cat $PREFIX/admin.env"
say "hazte dueño del mundo: entra y escribe en el chat /dueño <ese código> (luego /roles)"
say "registro: journalctl -u $SERVICE -f · estado: systemctl status $SERVICE"
[ "$HABITANTES" = 1 ] && say "habitantes IA: journalctl -u $HAB_SERVICE -f (quitarlos: systemctl stop $HAB_SERVICE) · cerebro: $([ -f "$PREFIX/cerebro.env" ] && echo "sí ($(grep -m1 '^CEREBRO_MODELO=' "$PREFIX/cerebro.env" | cut -d= -f2))" || echo "no (ponlo con --clave-ia)")"
say "construir: $CONSTRUIR (cámbialo con --construir todos|nadie)"
if [ "$AUTO" = 1 ]; then say "auto-actualizar: sí (pausa: touch $PREFIX/PAUSA · ver: journalctl -u $ACT_SERVICE)"; else say "auto-actualizar: no (actívalo con --auto-actualizar)"; fi
exit 0
__CARGA_DEBAJO__
